const path = require('path');
const { pathToFileURL } = require('url');
const root = '/w/node_modules/agents';
const version = require(path.join(root, 'package.json')).version;
(async () => {
  let mod;
  try {
    mod = await import(pathToFileURL(path.join(root, 'dist', 'chat', 'transport.js')).href);
  } catch (e) {
    console.error('ERROR: cannot load agents/chat/transport: ' + e.message);
    process.exit(2);
  }
  // The transport useAgentChat streams chat turns through.
  const { WebSocketChatTransport } = mod;
  if (typeof WebSocketChatTransport !== 'function') {
    console.error('ERROR: WebSocketChatTransport is not exported');
    process.exit(2);
  }
  const target = new EventTarget();
  const sent = [];
  const agent = {
    send: (data) => { sent.push(data); return true; },
    addEventListener: target.addEventListener.bind(target),
    removeEventListener: target.removeEventListener.bind(target)
  };
  const transport = new WebSocketChatTransport({ agent });
  const stream = await transport.sendMessages({
    chatId: 'c1',
    messages: [{ id: 'u1', role: 'user', parts: [{ type: 'text', text: 'hi' }] }],
    trigger: 'submit-message',
    messageId: undefined,
    abortSignal: undefined
  });
  const request = sent.map((s) => JSON.parse(s)).find((m) => m.type === 'cf_agent_use_chat_request');
  if (!request) {
    console.error('ERROR: no cf_agent_use_chat_request was sent');
    process.exit(2);
  }
  const frame = (chunk) => {
    const event = new Event('message');
    event.data = JSON.stringify({ type: 'cf_agent_use_chat_response', id: request.id, body: JSON.stringify(chunk), done: false });
    target.dispatchEvent(event);
  };
  frame({ type: 'start', messageId: 'a1' });
  frame({ type: 'text-start', id: 't1' });
  frame({ type: 'text-delta', id: 't1', delta: 'Hel' });
  // The socket closes before the terminal done frame.
  target.dispatchEvent(new Event('close'));
  const chunks = [];
  const reader = stream.getReader();
  const timer = setTimeout(() => {
    console.error('ERROR: stream did not end after the socket closed');
    process.exit(2);
  }, 5000);
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      chunks.push(value);
    }
  } catch (e) {
    clearTimeout(timer);
    console.error('ERROR: stream read rejected: ' + e.message);
    process.exit(2);
  }
  clearTimeout(timer);
  const types = chunks.map((c) => c.type);
  if (!types.includes('text-delta')) {
    console.error('ERROR: received content was dropped: ' + JSON.stringify(types));
    process.exit(2);
  }
  const err = chunks.find((c) => c.type === 'error');
  if (err) {
    console.log('OK: agents ' + version + ' ends the interrupted turn with an error chunk after the received text: ' + err.errorText);
    process.exit(0);
  }
  if (types[types.length - 1] === 'text-delta') {
    console.error('FAIL: agents ' + version + ' ends the stream cleanly after a socket close before done, so the truncated answer looks complete');
    process.exit(1);
  }
  console.error('ERROR: unexpected chunks ' + JSON.stringify(types));
  process.exit(2);
})().catch((e) => {
  console.error('ERROR: ' + e.message);
  process.exit(2);
});

